import sys

s = sys.stdin.read().split()[0]
n = len(s)
NEG = -10**9

def valid(t):
    return any(c in 'aeiou' for c in t) and any(c not in 'aeiou' for c in t)

dp = [NEG] * (n + 1)
dp[0] = 0
for i in range(1, n + 1):
    for j in range(i):
        if dp[j] > NEG and valid(s[j:i]):
            dp[i] = max(dp[i], dp[j] + 1)
print(dp[n] if dp[n] > 0 else 0)

